sys_script_include.script:
var filterModel = Class.create();
filterModel.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	filter: function(modelCategory) {
		gs.info('Filter erstellt für model_category: ' + modelCategory);
		//gs.addInfoMessage("Zeile5");
        if (!modelCategory) {
			gs.log('keine Model Category gefunden');
            return ''; // Wenn kein Wert vorhanden ist, wird ein leerer Filter zurückgegeben
        }

        var gr = new GlideRecord('cmdb_model');
        gr.addQuery('cmdb_model_category', modelCategory); // Filtere nach der übergebenen Kategorie
        gr.query();

        var sysIdList = [];
        while (gr.next()) {
            sysIdList.push(gr.getValue('sys_id'));
        }

        // Rückgabe des Filters im passenden Format ("sys_idIN...")
        return sysIdList.join(',');
    },
    type: 'filterModel'
});
